const data = $input.first().json;

const dbConfig = {
  customer_id: data.customer_id,
  db_name: `prismity_${data.customer_id.replace(/-/g, '_')}`,
  db_user: `user_${data.customer_id.replace(/-/g, '_').substring(0, 20)}`,
  db_password: require('crypto').randomBytes(24).toString('base64').replace(/[^a-zA-Z0-9]/g, '').substring(0, 32),
  server_ip: data.server.ip,
  root_password: data.server.root_password,
  domain: data.domain,
  owner: data.owner,
  properties: data.properties || [],
  nocodb_port: 8080,
  postgres_port: 5432
};

return [{ json: dbConfig }];

const dbConfig = $input.first().json;
const properties = dbConfig.properties || [];

const seedSQL = [];

for (let i = 0; i < properties.length; i++) {
  const prop = properties[i];
  const propertyId = `prop_${i + 1}`;

  seedSQL.push(`INSERT INTO property_configurations (property_id, property_name, address, city, bedrooms, max_guests, base_price, owner_contact, owner_email, owner_phone) VALUES ('${propertyId}', '${(prop.name || 'Property ' + (i+1)).replace(/'/g, "''")}', '${(prop.address || '').replace(/'/g, "''")}', '${(prop.city || '').replace(/'/g, "''")}', ${prop.bedrooms || 1}, ${prop.max_guests || 4}, ${prop.base_price || 100}, '${(dbConfig.owner.name || '').replace(/'/g, "''")}', '${(dbConfig.owner.email || '').replace(/'/g, "''")}', '${dbConfig.owner.phone || ''}') ON CONFLICT (property_id) DO NOTHING;`);
}

seedSQL.push(`INSERT INTO workflow_config (config_key, config_value, description) VALUES ('customer_id', '${dbConfig.customer_id}', 'Unique customer identifier') ON CONFLICT (config_key) DO NOTHING;`);
seedSQL.push(`INSERT INTO workflow_config (config_key, config_value, description) VALUES ('n8n_base_url', 'https://${dbConfig.domain}', 'N8N instance URL') ON CONFLICT (config_key) DO NOTHING;`);
seedSQL.push(`INSERT INTO workflow_config (config_key, config_value, description) VALUES ('nocodb_url', 'https://${dbConfig.domain}:8080', 'NocoDB interface URL') ON CONFLICT (config_key) DO NOTHING;`);

return [{
  json: {
    ...dbConfig,
    seed_sql: seedSQL.join('\n'),
    properties_count: properties.length
  }
}];

const dbConfig = $input.first().json;
const startTime = new Date($('When called by Master').first().json.deployment?.started_at || new Date());
const duration = Math.round((new Date() - startTime) / 1000);

return [{
  json: {
    status: 'success',
    phase: 'database_provisioning',
    duration: duration,

    database: {
      name: dbConfig.db_name,
      user: dbConfig.db_user,
      password: dbConfig.db_password,
      host: 'localhost',
      port: 5432,
      connection_string: `postgresql://${dbConfig.db_user}:${dbConfig.db_password}@localhost:5432/${dbConfig.db_name}`
    },

    nocodb: {
      url: `https://${dbConfig.domain}:8080`,
      status: 'running',
      description: 'Client data management interface'
    },

    tables_created: 21,
    indexes_created: 16,
    properties_seeded: dbConfig.properties_count || 0,

    message: 'PostgreSQL database and NocoDB deployed successfully'
  }
}];
